from collections import deque
def solve(I):
    H,W=len(I),len(I[0])
    O=[r[:] for r in I]
    accents=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c]!=1]
    # pockets: 4-connected components of 1s not touching border
    seen=[[False]*W for _ in range(H)]
    pockets=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]==1 and not seen[i][j]:
                comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny][nx]==1 and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                if not any(y==0 or y==H-1 or x==0 or x==W-1 for y,x in comp):
                    pockets.append(comp)
    for comp in pockets:
        best=min(accents,key=lambda a: min(abs(a[0]-y)+abs(a[1]-x) for y,x in comp))
        for y,x in comp: O[y][x]=best[2]
    return O
